CREATE TABLE simulation_runs (tenant_id text NOT NULL, run_id uuid NOT NULL, virtual_time timestamptz NOT NULL, admission_sequence bigint NOT NULL DEFAULT 0, step_sequence bigint NOT NULL DEFAULT 0, PRIMARY KEY(tenant_id,run_id));
CREATE TABLE budgets (tenant_id text NOT NULL, run_id uuid NOT NULL, budget_id text NOT NULL, currency text NOT NULL CHECK(currency IN ('EUR','USD')), limit_minor bigint NOT NULL CHECK(limit_minor>0), held bigint NOT NULL DEFAULT 0 CHECK(held>=0), consumed bigint NOT NULL DEFAULT 0 CHECK(consumed>=0), frozen boolean NOT NULL DEFAULT false, PRIMARY KEY(tenant_id,run_id,budget_id), FOREIGN KEY(tenant_id,run_id) REFERENCES simulation_runs, CHECK(held+consumed<=limit_minor));
CREATE TABLE authority_grants (tenant_id text NOT NULL, run_id uuid NOT NULL, grant_id text NOT NULL, budget_id text NOT NULL, subject_id text NOT NULL, merchant_id text NOT NULL, state text NOT NULL DEFAULT 'ACTIVE' CHECK(state IN ('ACTIVE','REVOKED')), version int NOT NULL DEFAULT 1, valid_from timestamptz NOT NULL, expires_at timestamptz NOT NULL, PRIMARY KEY(tenant_id,run_id,grant_id), FOREIGN KEY(tenant_id,run_id,budget_id) REFERENCES budgets);
CREATE TABLE payment_intents (tenant_id text NOT NULL, run_id uuid NOT NULL, intent_id uuid NOT NULL, merchant_id text NOT NULL, scenario_id text NOT NULL, state text NOT NULL, version int NOT NULL DEFAULT 1, checkout_revision int NOT NULL DEFAULT 0, PRIMARY KEY(tenant_id,run_id,intent_id), FOREIGN KEY(tenant_id,run_id) REFERENCES simulation_runs);
CREATE TABLE checkout_snapshots (tenant_id text NOT NULL, run_id uuid NOT NULL, intent_id uuid NOT NULL, revision int NOT NULL, digest text NOT NULL, canonical_bytes text NOT NULL, currency text NOT NULL CHECK(currency IN ('EUR','USD')), minor_units bigint NOT NULL CHECK(minor_units>0 AND minor_units<=999999999999), credential_reference text NOT NULL, expires_at timestamptz NOT NULL, PRIMARY KEY(tenant_id,run_id,intent_id,revision), FOREIGN KEY(tenant_id,run_id,intent_id) REFERENCES payment_intents);
CREATE TABLE payment_attempts (tenant_id text NOT NULL, run_id uuid NOT NULL, attempt_id uuid NOT NULL, intent_id uuid NOT NULL, checkout_revision int NOT NULL, grant_id text NOT NULL, grant_version int NOT NULL, subject_id text NOT NULL, owner text NOT NULL CHECK(owner='simulator-core'), PRIMARY KEY(tenant_id,run_id,attempt_id), UNIQUE(tenant_id,run_id,intent_id), FOREIGN KEY(tenant_id,run_id,intent_id,checkout_revision) REFERENCES checkout_snapshots, FOREIGN KEY(tenant_id,run_id,grant_id) REFERENCES authority_grants);
CREATE TABLE reservations (tenant_id text NOT NULL, run_id uuid NOT NULL, attempt_id uuid NOT NULL, budget_id text NOT NULL, minor_units bigint NOT NULL CHECK(minor_units>0), state text NOT NULL CHECK(state IN ('HELD','CONSUMED','RELEASED')), PRIMARY KEY(tenant_id,run_id,attempt_id), FOREIGN KEY(tenant_id,run_id,attempt_id) REFERENCES payment_attempts, FOREIGN KEY(tenant_id,run_id,budget_id) REFERENCES budgets);
CREATE TABLE financial_operations (tenant_id text NOT NULL, run_id uuid NOT NULL, operation_id uuid NOT NULL, attempt_id uuid NOT NULL, adapter_key uuid NOT NULL, request_digest text NOT NULL, admitted_sequence bigint, fact_sequence bigint NOT NULL DEFAULT 0, final_outcome text, PRIMARY KEY(tenant_id,run_id,operation_id), UNIQUE(tenant_id,run_id,attempt_id), UNIQUE(tenant_id,run_id,adapter_key), FOREIGN KEY(tenant_id,run_id,attempt_id) REFERENCES payment_attempts);
CREATE TABLE customer_actions (tenant_id text NOT NULL, run_id uuid NOT NULL, action_id uuid NOT NULL, operation_id uuid NOT NULL, subject_id text NOT NULL, checkout_digest text NOT NULL, state text NOT NULL CHECK(state IN ('OPEN','VERIFIED','DENIED','EXPIRED','CANCELLED')), expires_at timestamptz NOT NULL, version int NOT NULL DEFAULT 1, PRIMARY KEY(tenant_id,run_id,action_id), UNIQUE(tenant_id,run_id,operation_id), FOREIGN KEY(tenant_id,run_id,operation_id) REFERENCES financial_operations);
CREATE TABLE commands (tenant_id text NOT NULL, run_id uuid NOT NULL, principal_id text NOT NULL, route text NOT NULL, resource_id text NOT NULL, idempotency_key text NOT NULL, request_digest text NOT NULL, response_status int NOT NULL, response_body text NOT NULL, PRIMARY KEY(tenant_id,run_id,principal_id,route,resource_id,idempotency_key), FOREIGN KEY(tenant_id,run_id) REFERENCES simulation_runs);
CREATE TABLE outbox (tenant_id text NOT NULL, run_id uuid NOT NULL, operation_id uuid NOT NULL, kind text NOT NULL CHECK(kind IN ('PREPARE','DISPATCH','RECONCILE')), done boolean NOT NULL DEFAULT false, fence bigint NOT NULL DEFAULT 0, PRIMARY KEY(tenant_id,run_id,operation_id,kind), FOREIGN KEY(tenant_id,run_id,operation_id) REFERENCES financial_operations);
CREATE TABLE event_inbox (tenant_id text NOT NULL, run_id uuid NOT NULL, event_id uuid NOT NULL, operation_id uuid NOT NULL, fact_digest text NOT NULL, PRIMARY KEY(tenant_id,run_id,event_id), FOREIGN KEY(tenant_id,run_id,operation_id) REFERENCES financial_operations);
CREATE TABLE operation_evidence (tenant_id text NOT NULL, run_id uuid NOT NULL, event_id uuid NOT NULL, operation_id uuid NOT NULL, sequence bigint NOT NULL, outcome text NOT NULL, fact_digest text NOT NULL, PRIMARY KEY(tenant_id,run_id,event_id), FOREIGN KEY(tenant_id,run_id,operation_id) REFERENCES financial_operations);
CREATE TABLE audit_events (tenant_id text NOT NULL, run_id uuid NOT NULL, event_id uuid NOT NULL, intent_id uuid, state text NOT NULL, virtual_time timestamptz NOT NULL, step_sequence bigint NOT NULL, PRIMARY KEY(tenant_id,run_id,event_id), FOREIGN KEY(tenant_id,run_id) REFERENCES simulation_runs);
CREATE TABLE disputed_exposure (tenant_id text NOT NULL, run_id uuid NOT NULL, operation_id uuid NOT NULL, minor_units bigint NOT NULL, reason text NOT NULL, PRIMARY KEY(tenant_id,run_id,operation_id), FOREIGN KEY(tenant_id,run_id,operation_id) REFERENCES financial_operations);
CREATE TABLE simulator_operation_journal (tenant_id text NOT NULL, run_id uuid NOT NULL, adapter_key uuid NOT NULL, request_digest text NOT NULL, identity_json text NOT NULL, currency text NOT NULL, minor_units bigint NOT NULL, scenario_id text NOT NULL, outcome text NOT NULL CHECK(outcome IN ('PENDING','SUCCEEDED','NO_EFFECT')), sequence bigint NOT NULL, event_id uuid NOT NULL, PRIMARY KEY(tenant_id,run_id,adapter_key));
CREATE TABLE simulator_journal_events (tenant_id text NOT NULL, run_id uuid NOT NULL, event_id uuid NOT NULL, adapter_key uuid NOT NULL, request_digest text NOT NULL, identity_json text NOT NULL, currency text NOT NULL, minor_units bigint NOT NULL, outcome text NOT NULL, sequence bigint NOT NULL, PRIMARY KEY(tenant_id,run_id,event_id), FOREIGN KEY(tenant_id,run_id,adapter_key) REFERENCES simulator_operation_journal);
CREATE INDEX outbox_due_idx ON outbox(tenant_id,run_id,done,kind);
CREATE INDEX intent_state_idx ON payment_intents(tenant_id,run_id,state);
